args.command:
node --input-type=module -e '
import { JSDOM } from "jsdom";
const dom = new JSDOM("<!doctype html><html><body></body></html>");
globalThis.window = dom.window;
globalThis.document = dom.window.document;
globalThis.navigator = dom.window.navigator;

const { screen, render } = await import("@testing-library/react");
const React = await import("react");

function TestComp() {
  return React.createElement("div", null,
    React.createElement("p", null, "Active Users: 2"),
    React.createElement("p", null, "Inactive Users: 1"),
    React.createElement("p", null, "Percentage of Active Users: 67%")
  );
}

render(React.createElement(TestComp));

try {
  screen.getByText(/Active Users: 2/i);
  console.log("getByText(/Active Users: 2/i) matched!");
} catch (e) {
  console.log("getByText(/Active Users: 2/i) threw:", e.message);
}

try {
  screen.getByText(/Active Users:/i);
  console.log("getByText(/Active Users:/i) matched!");
} catch (e) {
  console.log("getByText(/Active Users:/i) threw:", e.message.split("\n")[0]);
}

try {
  screen.getByText(/Active Users/i);
  console.log("getByText(/Active Users/i) matched!");
} catch (e) {
  console.log("getByText(/Active Users/i) threw:", e.message.split("\n")[0]);
}
'

