// @vitest-environment jsdom
import React from 'react'
import { render, screen } from '@testing-library/react'
import { describe, it, expect } from 'vitest'

function UserStatsOptionA() {
  return (
    <div>
      <h2>User Statistics</h2>
      <p>Active Users: 2</p>
      <p>Inactive Users: 1</p>
      <p>Percentage of Active Users: 67%</p>
    </div>
  )
}

function UserStatsOptionB() {
  return (
    <div>
      <h2>User Statistics</h2>
      <p>Active Users: 2</p>
      <p>Inactive Users: 1</p>
      <p>Active Percentage: 67%</p>
    </div>
  )
}

describe('test options', () => {
  it('Option A with getByText(/Active Users/i)', () => {
    const { unmount } = render(<UserStatsOptionA />)
    try {
      screen.getByText(/Active Users/i)
      console.log('Option A matched /Active Users/i without error')
    } catch (e: any) {
      console.log('Option A threw error on /Active Users/i:', e.message.split('\n')[0])
    }
    unmount()
  })

  it('Option A with getByText(/Active Users: 2/i)', () => {
    const { unmount } = render(<UserStatsOptionA />)
    screen.getByText(/Active Users: 2/i)
    unmount()
  })

  it('Option B with getByText(/Active Users/i)', () => {
    const { unmount } = render(<UserStatsOptionB />)
    screen.getByText(/Active Users/i)
    unmount()
  })
})

